def esc(s):return s.replace('&',r'\&').replace('%',r'\%').replace('_',r'\_')
with (ROOT/'references.bib').open('w') as f:
    for r in refs:
        f.write('@misc{'+r['key']+',\n')
        for field in ['author','title','year','url','doi','note']:
            if r[field]:f.write('  '+field+' = {'+(r[field] if field in ['url','doi'] else esc(r[field]))+'},\n')
        f.write('}\n\n')
(ROOT/'reference_evidence.json').write_text(json.dumps(refs,ensure_ascii=False,indent=2)+'\n')
print(f'Saved {len(refs)} verified opened references with precise verification scope.')
